// Poison stacks snapshot the projectile's damage. Ticks cannot crit or leech.
function applyProjectileAilment(e,shot){if(e.hp<=0||shot.enemy||shot.skill!=='arrow'||!Number.isFinite(shot.damage)||shot.damage<=0)return;e.poison??=[];if(e.poison.length>=5)e.poison.shift();e.poison.push({remaining:3,elapsed:0,power:shot.damage*.1})}
function tickAilments(e,dt){if(e.hp<=0||!e.poison||dt<=0)return;for(let stack of e.poison){let elapsed=Math.min(dt,stack.remaining);stack.remaining=Math.max(0,stack.remaining-elapsed);stack.elapsed+=elapsed;while(stack.elapsed>=.5-1e-9&&e.hp>0){stack.elapsed-=.5;e.dotTick=true;try{hit(e,stack.power)}finally{e.dotTick=false}}}e.poison=e.hp>0?e.poison.filter(s=>s.remaining>1e-9):[]}
function drawAilmentStatus(e,s,size){let labels=[];if(e.poison?.length)labels.push('毒 '+e.poison.length);if(e.slow>0)labels.push('減速');if(!labels.length)return;ctx.save();ctx.fillStyle=e.poison?.length?'#a6e6a4':'#9bd8ec';ctx.textAlign='center';ctx.font='bold 10px sans-serif';ctx.fillText(labels.join(' / '),s.x,s.y-size*.8+16);if(e.poison?.length){for(let i=0;i<3;i++){let a=clock*2+i*Math.PI*2/3,t=project(e.x+Math.cos(a)*24,e.y+Math.sin(a)*24);circle(t.x,t.y-8-Math.sin(clock*3+i)*5,2.5,'#8bdc8f')}}ctx.restore()}
